export type DemoPhotoId = keyof typeof DEMO_PHOTOS;

export function demoPhotos(ids: DemoPhotoId[], captions?: Partial<Record<DemoPhotoId, string>>): GiftPhoto[] {
  return ids.map((id) => ({ ...DEMO_PHOTOS[id], caption: captions?.[id] ?? DEMO_PHOTOS[id].caption }));
}
